// Bollard UI — json-field · MIT licence · https://bollard-ui.vercel.app/components/json-field

/**
 * A small JSON checker that, unlike JSON.parse, reports the same exact position in every browser
 * and recognises the classic hand-editing mistakes so each can be fixed in one step.
 */

export type JsonMistake = "trailing-comma" | "quotes" | "unquoted-key" | "comment" | "python" | "missing-comma" | "unclosed"

export interface JsonIssue {
  message: string
  /** UTF-16 offset of the problem. */
  index: number
  /** 1-based. */
  line: number
  /** 1-based. */
  column: number
  /** Set when the mistake is one `fixJson` can repair. */
  mistake?: JsonMistake
}

type Token = { type: "str" | "comment" | "punct" | "word" | "ws" | "bad"; start: number; end: number; quote?: string; closed?: boolean }

const OPEN_QUOTES: Record<string, string> = { '"': '"', "'": "'", "“": "”“", "”": "”“", "„": "”“", "‘": "’‘", "’": "’‘", "‚": "’‘" }
const NUMBER = /^-?(0|[1-9]\d*)(\.\d+)?([eE][+-]?\d+)?$/
const PYTHON: Record<string, string> = { True: "true", False: "false", None: "null" }

/** Splits text into JSON-ish tokens, tolerating comments, single and smart quotes, and bare words. */
function lex(text: string): Token[] {
  const tokens: Token[] = []
  let i = 0
  while (i < text.length) {
    const start = i
    const ch = text[i]
    if (/[ \t\n\r]/.test(ch)) {
      while (i < text.length && /[ \t\n\r]/.test(text[i])) i++
      tokens.push({ type: "ws", start, end: i })
    } else if (text.startsWith("//", i) || text.startsWith("/*", i)) {
      const end = ch === "/" && text[i + 1] === "/" ? text.indexOf("\n", i) : text.indexOf("*/", i + 2) + 2
      i = end <= 1 || end === -1 ? text.length : end
      tokens.push({ type: "comment", start, end: i })
    } else if (OPEN_QUOTES[ch]) {
      const closers = OPEN_QUOTES[ch]
      i++
      while (i < text.length && !closers.includes(text[i]) && text[i] !== "\n") i += text[i] === "\\" ? 2 : 1
      const closed = i < text.length && closers.includes(text[i])
      if (closed) i++
      tokens.push({ type: "str", start, end: Math.min(i, text.length), quote: ch, closed })
    } else if ("{}[]:,".includes(ch)) {
      tokens.push({ type: "punct", start, end: ++i })
    } else if (/[^\s{}[\]:,"'“”„‘’‚/]/.test(ch)) {
      while (i < text.length && /[^\s{}[\]:,"'“”„‘’‚/]/.test(text[i])) i++
      tokens.push({ type: "word", start, end: i })
    } else {
      tokens.push({ type: "bad", start, end: ++i })
    }
  }
  return tokens
}

/** 1-based line and column of a UTF-16 offset. */
export function lineColumn(text: string, index: number) {
  const before = text.slice(0, index)
  const line = before.split("\n").length
  return { line, column: index - before.lastIndexOf("\n") }
}

class Stop {
  constructor(public message: string, public index: number, public mistake?: JsonMistake) {}
}

/** Returns the first problem in `text`, or null when it is valid JSON (or empty). */
export function checkJson(text: string): JsonIssue | null {
  if (!text.trim()) return null
  const tokens = lex(text).filter((t) => t.type !== "ws")
  const raw = (t: Token) => text.slice(t.start, t.end)
  const opened: Token[] = []
  let p = 0

  const unexpected = (t: Token | undefined, expected: string): never => {
    if (!t) {
      const open = opened[opened.length - 1]
      if (open) throw new Stop(`The ${raw(open)} on line ${lineColumn(text, open.start).line} is never closed.`, text.length, "unclosed")
      throw new Stop("The JSON ends too early.", text.length)
    }
    if (t.type === "comment") throw new Stop("JSON doesn’t allow comments.", t.start, "comment")
    if (t.type === "str" && t.quote !== '"') throw new Stop(`Use straight double quotes (") for strings, not ${t.quote}.`, t.start, "quotes")
    if (t.type === "word" && PYTHON[raw(t)]) throw new Stop(`${raw(t)} isn’t JSON; write ${PYTHON[raw(t)]}.`, t.start, "python")
    throw new Stop(`Expected ${expected} here.`, t.start)
  }

  const value = (): void => {
    const t = tokens[p]
    if (t?.type === "punct" && (raw(t) === "{" || raw(t) === "[")) return container(t)
    if (t?.type === "str" && t.quote === '"') {
      if (!t.closed) throw new Stop("This string is never closed.", t.start)
      try {
        JSON.parse(raw(t))
      } catch {
        throw new Stop("This string has an invalid escape or a raw tab or control character.", t.start)
      }
      p++
      return
    }
    if (t?.type === "word" && (NUMBER.test(raw(t)) || ["true", "false", "null"].includes(raw(t)))) {
      p++
      return
    }
    unexpected(t, "a value")
  }

  const container = (open: Token) => {
    const isObject = raw(open) === "{"
    const close = isObject ? "}" : "]"
    opened.push(open)
    p++
    let afterComma: Token | null = null
    for (;;) {
      const t = tokens[p]
      if (t?.type === "punct" && raw(t) === close) {
        if (afterComma) throw new Stop(`Remove the comma before ${close}.`, afterComma.start, "trailing-comma")
        break
      }
      if (isObject) {
        const next = tokens[p + 1]
        if (t?.type === "word" && next?.type === "punct" && raw(next) === ":") throw new Stop("Property names need double quotes.", t.start, "unquoted-key")
        if (t?.type !== "str" || t.quote !== '"') unexpected(t, `a "property name" or ${close}`)
        value()
        const colon = tokens[p]
        if (colon?.type !== "punct" || raw(colon) !== ":") unexpected(colon, ": after the property name")
        p++
      }
      value()
      const sep = tokens[p]
      if (sep?.type === "punct" && raw(sep) === ",") {
        afterComma = sep
        p++
      } else if (sep?.type === "punct" && raw(sep) === close) {
        break
      } else if (sep && (sep.type === "str" || sep.type === "word" || raw(sep) === "{" || raw(sep) === "[")) {
        throw new Stop(`Missing comma before ${raw(sep).slice(0, 12)}.`, tokens[p - 1].end, "missing-comma")
      } else {
        unexpected(sep, `, or ${close}`)
      }
      if (afterComma && tokens[p] !== undefined && !(tokens[p].type === "punct" && raw(tokens[p]) === close)) afterComma = null
    }
    opened.pop()
    p++
  }

  try {
    value()
    const extra = tokens[p]
    if (extra?.type === "punct" && "}]".includes(raw(extra))) throw new Stop(`There’s an extra ${raw(extra)} with nothing to close.`, extra.start)
    if (extra) unexpected(extra, "the end of the JSON")
    JSON.parse(text) // Belt and braces: anything this checker missed still surfaces.
    return null
  } catch (error) {
    const stop = error instanceof Stop ? error : new Stop(error instanceof Error ? error.message : String(error), 0)
    return { message: stop.message, index: stop.index, ...lineColumn(text, stop.index), mistake: stop.mistake }
  }
}

/** Repairs every occurrence of one classic mistake, leaving string contents untouched. */
export function fixJson(text: string, mistake: JsonMistake): string {
  const tokens = lex(text)
  const raw = (t: Token) => text.slice(t.start, t.end)
  const sig = tokens.filter((t) => t.type !== "ws" && t.type !== "comment")
  const nextSig = (t: Token) => sig[sig.indexOf(t) + 1]

  if (mistake === "unclosed") {
    const stack: string[] = []
    for (const t of sig) {
      if (t.type !== "punct") continue
      const c = raw(t)
      if (c === "{" || c === "[") stack.push(c === "{" ? "}" : "]")
      else if (c === "}" || c === "]") stack.pop()
    }
    const sep = text.includes("\n") ? "\n" : ""
    return text.trimEnd() + stack.reverse().map((c) => sep + c).join("")
  }

  if (mistake === "comment") {
    let out = text
    for (const t of tokens.filter((x) => x.type === "comment").reverse()) {
      const lineStart = text.lastIndexOf("\n", t.start - 1) + 1
      const ownLine = !text.slice(lineStart, t.start).trim() && (t.end === text.length || text[t.end] === "\n")
      // A comment on its own line takes the line with it; a trailing one takes the spaces before it.
      const from = ownLine ? lineStart : t.start - (text.slice(lineStart, t.start).match(/[ \t]*$/)?.[0].length ?? 0)
      out = out.slice(0, from) + out.slice(ownLine && t.end < text.length ? t.end + 1 : t.end)
    }
    return out
  }

  return tokens.map((t) => {
    const s = raw(t)
    switch (mistake) {
      case "quotes": {
        if (t.type !== "str" || t.quote === '"') return s
        const body = s.slice(1, t.closed ? -1 : undefined).replace(/\\'/g, "'").replace(/(^|[^\\])"/g, '$1\\"')
        return `"${body}"`
      }
      case "unquoted-key":
        return t.type === "word" && raw(nextSig(t) ?? t) === ":" ? `"${s}"` : s
      case "python":
        return t.type === "word" && PYTHON[s] ? PYTHON[s] : s
      case "trailing-comma": {
        const next = t.type === "punct" && s === "," ? nextSig(t) : undefined
        return next && (raw(next) === "}" || raw(next) === "]") ? "" : s
      }
      case "missing-comma": {
        const next = nextSig(t)
        const endsValue = t.type === "str" || t.type === "word" || s === "}" || s === "]"
        const startsValue = next && (next.type === "str" || next.type === "word" || raw(next) === "{" || raw(next) === "[")
        const isKey = t.type === "str" && raw(nextSig(t) ?? t) === ":"
        return endsValue && startsValue && !isKey ? s + "," : s
      }
      default:
        return s
    }
  }).join("")
}

"use client"

// Bollard UI — json-field · MIT licence · https://bollard-ui.vercel.app/components/json-field

import * as React from "react"
import { Braces, CircleCheck, TriangleAlert } from "lucide-react"

import { cn } from "@/lib/utils"
import { checkJson, fixJson, type JsonIssue, type JsonMistake } from "./json-check"

export { checkJson, fixJson, lineColumn } from "./json-check"
export type { JsonIssue, JsonMistake } from "./json-check"

const DEFAULT_FIX_LABELS: Record<JsonMistake, string> = {
  "trailing-comma": "Remove trailing commas",
  quotes: "Use double quotes",
  "unquoted-key": "Quote the keys",
  comment: "Remove comments",
  python: "Use true / false / null",
  "missing-comma": "Add the comma",
  unclosed: "Close it",
}

export interface JsonFieldProps
  extends Omit<React.ComponentProps<"textarea">, "value" | "defaultValue" | "onChange"> {
  /** Visible label. */
  label?: string
  /** Helper text shown while the field is empty. */
  hint?: string
  /** Controlled value. */
  value?: string
  /** Initial value when uncontrolled. */
  defaultValue?: string
  /** Called with the text on every change, including fixes and formatting. */
  onValueChange?: (value: string) => void
  /** Pause in ms before a problem is shown while typing. Leaving the field shows it at once. */
  delay?: number
  /** Indent used by the Format button. */
  indent?: number
  /** Format button text. */
  formatLabel?: string
  /** Shown under valid JSON. */
  validMessage?: string
  /** Labels of the one-tap fixes, per mistake. */
  fixLabels?: Partial<Record<JsonMistake, string>>
  /** Text of the button that selects the problem in the textarea. */
  showLabel?: string
  /** Formats the position shown before each problem. */
  formatPosition?: (line: number, column: number) => string
}

const fixClass =
  "inline-flex h-6 items-center gap-1 rounded-md border border-amber-500/40 px-2 font-medium text-amber-900 transition-colors hover:bg-amber-500/10 dark:text-amber-200 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"
const keyframes = `@keyframes cui-json-field-caret{0%{transform:translateY(-4px);opacity:0}100%{transform:none;opacity:1}}`

/** A one-line code frame: the offending line (trimmed to fit) with a caret under the exact column. */
function CodeFrame({ text, issue }: { text: string; issue: JsonIssue }) {
  const source = (text.split("\n")[issue.line - 1] ?? "").replace(/\t/g, " ")
  const from = Math.max(0, issue.column - 1 - 22)
  const snippet = (from > 0 ? "…" : "") + source.slice(from, from + 40) + (source.length > from + 40 ? "…" : "")
  const caret = issue.column - 1 - from + (from > 0 ? 1 : 0)
  const gutter = String(issue.line)
  return (
    <pre aria-hidden className="overflow-hidden rounded-md border bg-muted/40 px-2 py-1.5 font-mono text-xs leading-5 text-foreground">
      <span className="text-muted-foreground">{gutter} │ </span>
      {snippet}
      {"\n"}
      <span className="text-muted-foreground">{" ".repeat(gutter.length)} │ </span>
      {" ".repeat(caret)}
      <span key={issue.index} className="inline-block font-bold text-amber-600 motion-safe:animate-[cui-json-field-caret_250ms_ease-out] dark:text-amber-400">^</span>
    </pre>
  )
}

/**
 * A JSON textarea that catches broken config before it is saved. It validates as you type,
 * points at the exact line and column with a caret (the same in every browser, unlike
 * JSON.parse messages), and repairs the classic hand-editing mistakes in one tap: trailing
 * commas, single or smart quotes, unquoted keys, comments, Python's True/None, a missing comma
 * or an unclosed brace. Fixes are token-aware, so text inside strings is never touched.
 */
export function JsonField({
  label = "JSON",
  hint,
  value,
  defaultValue = "",
  onValueChange,
  delay = 600,
  indent = 2,
  formatLabel = "Format",
  validMessage = "Valid JSON",
  fixLabels,
  showLabel = "Show me",
  formatPosition = (line, column) => `Line ${line}, column ${column}:`,
  id,
  className,
  rows = 8,
  onBlur,
  ref,
  ...props
}: JsonFieldProps) {
  const [inner, setInner] = React.useState(defaultValue)
  const [settled, setSettled] = React.useState(defaultValue)
  const areaRef = React.useRef<HTMLTextAreaElement>(null)
  const autoId = React.useId()
  const fieldId = id ?? autoId
  const text = value ?? inner

  React.useImperativeHandle(ref, () => areaRef.current as HTMLTextAreaElement)

  React.useEffect(() => {
    const timer = setTimeout(() => setSettled(text), delay)
    return () => clearTimeout(timer)
  }, [text, delay])

  const issue = React.useMemo(() => checkJson(text), [text])
  const shown = settled === text ? issue : null
  const labels = { ...DEFAULT_FIX_LABELS, ...fixLabels }

  const update = (next: string, settle = false) => {
    if (value === undefined) setInner(next)
    if (settle) setSettled(next)
    onValueChange?.(next)
  }

  const select = (at: number) => {
    const area = areaRef.current
    if (!area) return
    area.focus()
    area.setSelectionRange(at, Math.min(at + 1, text.length))
    // Scroll the line into view: setSelectionRange alone doesn't in every browser.
    const lineHeight = parseFloat(getComputedStyle(area).lineHeight) || 20
    area.scrollTop = Math.max(0, (text.slice(0, at).split("\n").length - 3) * lineHeight)
  }

  return (
    <div data-slot="json-field" className={cn("grid w-full max-w-md gap-1.5", className)}>
      <style>{keyframes}</style>
      <div className="flex items-center justify-between gap-2">
        <label htmlFor={fieldId} className="text-sm font-medium">
          {label}
        </label>
        <button
          type="button"
          disabled={!text.trim() || !!issue}
          onClick={() => update(JSON.stringify(JSON.parse(text), null, indent), true)}
          className="inline-flex h-7 items-center gap-1.5 rounded-md px-2 text-xs font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground disabled:pointer-events-none disabled:opacity-50 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"
        >
          <Braces aria-hidden className="size-3.5" />
          {formatLabel}
        </button>
      </div>
      <textarea
        ref={areaRef}
        id={fieldId}
        rows={rows}
        wrap="off"
        value={text}
        spellCheck={false}
        autoCapitalize="none"
        autoCorrect="off"
        onChange={(event) => update(event.target.value)}
        onBlur={(event) => {
          setSettled(text)
          onBlur?.(event)
        }}
        aria-invalid={shown ? true : undefined}
        aria-describedby={`${fieldId}-status`}
        data-warning={shown ? "" : undefined}
        className="w-full min-w-0 resize-y rounded-md border bg-transparent px-3 py-2 font-mono text-sm leading-5 shadow-xs transition-[color,box-shadow] outline-none [tab-size:2] placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 dark:bg-input/30 data-warning:border-amber-500 dark:data-warning:border-amber-400"
        {...props}
      />
      <div id={`${fieldId}-status`} aria-live="polite" className="min-h-6 text-xs">
        {shown ? (
          <div className="grid gap-1.5">
            <div className="flex gap-1.5 text-amber-700 dark:text-amber-400">
              <span className="flex h-6 shrink-0 items-center">
                <TriangleAlert aria-hidden className="size-3.5" />
              </span>
              <span className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1">
                <span className="py-1">
                  <span className="font-medium">{formatPosition(shown.line, shown.column)}</span>{" "}
                  {shown.message}
                </span>
                {shown.mistake ? (
                  <button type="button" onClick={() => update(fixJson(text, shown.mistake!), true)} className={fixClass}>
                    {labels[shown.mistake]}
                  </button>
                ) : null}
                <button type="button" onClick={() => select(shown.index)} className="h-6 rounded-md px-1.5 font-medium underline-offset-2 hover:underline outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50">
                  {showLabel}
                </button>
              </span>
            </div>
            <CodeFrame text={text} issue={shown} />
          </div>
        ) : text.trim() && !issue ? (
          <p className="flex items-center gap-1.5 py-1 text-emerald-700 dark:text-emerald-400">
            <CircleCheck aria-hidden className="size-3.5" />
            {validMessage}
          </p>
        ) : hint && !text.trim() ? (
          <p className="py-1 text-muted-foreground">{hint}</p>
        ) : null}
      </div>
    </div>
  )
}
